<template><div><img v-if="url" :src="url" :alt="alt||'商品图片'" :class="large?'ui-product-large':'ui-image'" :style="large?'display:block;max-width:100%;max-height:430px;object-fit:contain;margin:12px 0':''"/><span v-else class="ui-meta">{{error?'图片不可读':fileId?'图片读取中':'未提供图片'}}</span></div></template>
<script>import {uiPreview} from '@/api/stage1-usability';export default {props:{fileId:String,alt:String,large:Boolean},data:()=>({url:null,error:'',ticket:0}),watch:{fileId:{immediate:true,handler(){this.reload();}}},beforeDestroy(){this.ticket++;if(this.url)URL.revokeObjectURL(this.url);},methods:{async reload(){const ticket=++this.ticket;if(this.url)URL.revokeObjectURL(this.url);this.url=null;this.error='';if(!this.fileId)return;try{const v=await uiPreview(this.fileId);if(ticket!==this.ticket){URL.revokeObjectURL(v.url);return;}if(!v.mimeType.startsWith('image/')){URL.revokeObjectURL(v.url);throw Error('非图片附件');}this.url=v.url;}catch(e){if(ticket===this.ticket)this.error=e.message;}}}};</script>
